    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>দোকানের অটো-রিপ্লাই নিয়ম: “মেসেজে ‘ফেরত’ থাকলে রিটার্ন নীতি পাঠাও”। গ্রাহক লিখলেন: “ফেরত চাই না, শুধু জানতে চাই অর্ডার কোথায়”—আর পেলেন রিটার্ন নীতি! উদাহরণ থেকে আচরণ নিলে কি এটা ঠিক হবে, নাকি অন্য ধরনের ভুল হবে?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>একই ইনপুটে নিয়মভিত্তিক ও উদাহরণ-ভিত্তিক আচরণ তুলনা করতে পারবেন</li><li>দুই পদ্ধতির একটি করে ব্যর্থতার উদাহরণ তৈরি করতে পারবেন</li><li>সিমুলেশনকে trained model না বলার কারণ ব্যাখ্যা করতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 30 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/models-params-data/">Model, Parameter, Dataset, Feature, Label</a></li><li><a href="/ai-academy/lesson/learning-roadmap/">শেখার রোডম্যাপ</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p>আমরা দুটি পদ্ধতি পাশাপাশি চালাব:</p><ul><li><strong>নিয়মভিত্তিক:</strong> প্রোগ্রামার একটি তালিকা লেখেন: শব্দ X থাকলে বিভাগ Y। প্রথম যে নিয়ম মেলে সেটাই উত্তর। স্বচ্ছ ও অনুমানযোগ্য, কিন্তু অপ্রত্যাশিত বাক্যে ভঙ্গুর।</li><li><strong>উদাহরণ-মিল (nearest example):</strong> কয়েকটি লেবেল-করা উদাহরণ রাখা হয়। নতুন মেসেজের সাথে প্রতিটি উদাহরণের কতগুলো শব্দ মেলে গোনা হয়; সবচেয়ে বেশি মেলা উদাহরণের লেবেল উত্তর। নতুন উদাহরণ যোগ করলেই আচরণ বদলায়—নিয়ম লিখতে হয় না।</li></ul><div class="wgba-note wgba-note-warn">এটি <strong>সিমুলেশন</strong>। এখানে কোনো parameter training হয় না, কোনো gradient নেই। বাস্তব ML (অধ্যায় ৪) উদাহরণ থেকে parameter শেখে; এখানে শুধু “উদাহরণ থেকে আচরণ” ধারণাটি দেখানো হচ্ছে।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> নিয়ম হলো দারোয়ানের হাতে একটি তালিকা: “লাল কার্ড থাকলে ঢুকতে দাও”। উদাহরণ-মিল হলো দারোয়ান যিনি আগের অতিথিদের মুখ মনে রেখে নতুন অতিথি কার মতো দেখতে তা বিচার করেন।</p><p><strong>কোথায় ভাঙে:</strong> মানুষ দারোয়ান মুখের অর্থপূর্ণ বৈশিষ্ট্য দেখেন। আমাদের সিমুলেশন শুধু হুবহু একই শব্দ গোনে—“কোথায়” আর “কোথায়?” (প্রশ্নবোধক চিহ্নসহ) কেও আলাদা শব্দ ভাবে।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>মেসেজ: <q>ফেরত চাই না, অর্ডার কোথায়</q></p><ol><li><strong>নিয়ম:</strong> প্রথম নিয়ম “ফেরত” → মেলে → বিভাগ = return। ভুল।</li><li><strong>উদাহরণ-মিল:</strong> শব্দগুলো: ফেরত, চাই, না, অর্ডার, কোথায়।</li><li>উদাহরণ “অর্ডার কোথায়” (status): মিল = অর্ডার, কোথায় = ২।</li><li>উদাহরণ “ফেরত চাই” (return): মিল = ফেরত, চাই = ২।</li><li>টাই! কোডে প্রথম সর্বোচ্চ স্কোর রাখা হয়, তাই উত্তর নির্ভর করে উদাহরণের ক্রমের ওপর—এটিও একটি দুর্বলতা।</li></ol><p>শিক্ষা: দুই পদ্ধতিই “না” শব্দের অর্থ ধরে না। অর্থ ধরতে আরও ভালো উপস্থাপনা (embedding, অধ্যায় ৭) ও শেখা মডেল লাগে।</p></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><p>নিচের কোড চালান। তারপর <code>message</code> বদলে অন্তত তিনটি মেসেজ পরীক্ষা করুন—একটি যেখানে নিয়ম জেতে, একটি যেখানে উদাহরণ-মিল জেতে, একটি যেখানে দুটোই ভুল করে।</p><h3>সিমুলেশন — trained model নয়</h3><div class="wgba-playground-slot" data-exercise="ex-01-08-rule-vs-examples"><pre class="wgba-code"><code>// সিমুলেশন: নিয়মভিত্তিক বনাম উদাহরণ-মিল (trained model নয়)
const rules = [
  { word: &quot;ফেরত&quot;, label: &quot;return&quot; },
  { word: &quot;দাম&quot;, label: &quot;price&quot; },
];
const examples = [
  { text: &quot;অর্ডার কোথায়&quot;, label: &quot;status&quot; },
  { text: &quot;ডেলিভারি কবে আসবে&quot;, label: &quot;status&quot; },
  { text: &quot;ফেরত চাই&quot;, label: &quot;return&quot; },
  { text: &quot;দাম কত&quot;, label: &quot;price&quot; },
];

function byRules(msg) {
  for (const r of rules) {
    if (msg.includes(r.word)) return r.label;
  }
  return &quot;unknown&quot;;
}

function words(s) {
  return s.replace(/[?,!।]/g, &quot; &quot;).split(&quot; &quot;).filter(w =&gt; w.length &gt; 0);
}

function byExamples(msg) {
  const m = words(msg);
  let best = &quot;unknown&quot;;
  let bestScore = 0;
  for (const ex of examples) {
    const score = words(ex.text).filter(w =&gt; m.includes(w)).length;
    if (score &gt; bestScore) {
      bestScore = score;
      best = ex.label;
    }
  }
  return best + &quot; (মিল=&quot; + bestScore + &quot;)&quot;;
}

const tests = [
  &quot;আমার অর্ডার কোথায়?&quot;,
  &quot;ফেরত চাই না, শুধু জানতে চাই ডেলিভারি কবে আসবে&quot;,
  &quot;এই শার্টের মূল্য কত&quot;,
];
for (const message of tests) {
  console.log(message);
  console.log(&quot;  নিয়ম:&quot;, byRules(message), &quot;| উদাহরণ:&quot;, byExamples(message));
}</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>rules</code>: প্রতিটি নিয়ম একটি শব্দ ও একটি লেবেল। <code>byRules</code> ক্রমানুসারে দেখে, প্রথম মিলেই ফেরত দেয়।</li><li><code>words</code>: বিরামচিহ্ন সরিয়ে স্পেস দিয়ে ভাগ করে শব্দের অ্যারে বানায়।</li><li><code>byExamples</code>: প্রতিটি উদাহরণের শব্দের মধ্যে কতগুলো মেসেজে আছে গোনে (<code>filter(...).length</code>)। বেশি স্কোর হলে সেটিকে সেরা হিসেবে রাখে। কোনো মিল না থাকলে “unknown”।</li><li>শেষের লুপ প্রতিটি পরীক্ষার মেসেজে দুই পদ্ধতির ফল একসাথে দেখায়।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>দুই পদ্ধতিকে আলাদা ফাংশনে রাখায় একই ইনপুটে তাদের ভিন্ন ভুল সহজে দেখা যায়। স্কোর আউটপুটে দেখানো হয়েছে যাতে “কেন এই উত্তর” তা লুকানো না থাকে।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>নিয়ম: স্বচ্ছ কিন্তু ভঙ্গুর</li><li>উদাহরণ-মিল: নতুন উদাহরণে আচরণ বদলায়, কিন্তু শব্দ-মিল অর্থ বোঝে না</li><li>সিমুলেশনকে trained model বলা যাবে না</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>JavaScript সিনট্যাক্সের প্রতিটি অংশ—অধ্যায় ২-এ শিখবেন</li><li>এখানকার স্কোরিং সূত্র</li></ul></div></details>
